// eslint-disable-next-line no-restricted-imports
import {on} from 'delegated-events'
import {requestSubmit} from '@github-ui/form-utils'

// Handles selection of ref from ref-selector.ts, which wasn't quite intended for this use case...
on('click', '.js-codespaces-branch', event => {
  const target = event.currentTarget as HTMLElement
  if (!target) return
  const refName = target.getAttribute('data-refname') || ''
  const refInput = document.querySelector('input#codespace_ref')!
  refInput.setAttribute('value', refName)
  if (refInput.getAttribute('data-autosubmit')) {
    const form = refInput.closest('form')
    if (form) {
      requestSubmit(form)
    }
  }

  // mark the branch as set in the widget and close the <details>
  const summary = document.querySelector('.js-selected-branch')!
  const selectedEl = document.querySelector(".js-codespaces-branch[aria-checked='true']")
  if (selectedEl) {
    selectedEl.setAttribute('aria-checked', 'false')
  }

  target.setAttribute('aria-checked', 'true')

  summary.textContent = refName
  target.closest('details')!.open = false
  event.preventDefault()
  return false
})

// Handles selection of ref from ref-selector-partial.tsx
on('ref-selector-partial:change', '.js-codespaces-ref-selector-partial', (event: CustomEvent) => {
  const {autosubmit, refName} = event.detail
  if (!refName) return

  const refInput = document.querySelector('input#codespace_ref')
  if (!refInput) return

  if (autosubmit) {
    const form = document.querySelector('.js-new-codespace-form')?.closest('form')
    if (form) {
      requestSubmit(form)
    }
  }

  event.preventDefault()
  return false
})
